uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;
uniform float u_density;
uniform float u_connection_radius;
uniform float u_pulse_intensity;
uniform float u_color_base;
uniform float u_color_pulse;

// New Portal Parameters
uniform float u_portal_twist;
uniform float u_event_horizon;

out vec4 fragColor;

// --- Helper Functions ---

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

vec2 hash22(vec2 p) {
    float n = hash21(p);
    return vec2(n, hash21(p + n));
}

float distLine(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// Draw a synapse connection
void addConnection(vec2 f, vec2 p1, vec2 offs, vec2 dir, vec2 id, float t, float coreSharpness, float haloSharpness, float fade, vec3 baseCol, vec3 pulseCol, float connRadius, float pulseInt, inout vec3 layerColor) {
    vec2 offs2 = offs + dir;
    vec2 p2 = offs2 + 0.5 + 0.4 * sin(t * 2.0 + hash22(id + offs2) * 6.28);
    float dConn = distance(p1, p2);

    if(dConn < connRadius) {
        float dLine = distLine(f, p1, p2);

        // Firing Pulse Logic
        float pulseTime = t * 10.0 + hash21(id + offs) * 20.0;
        float pulse = smoothstep(0.9, 1.0, sin(dConn * 6.0 - pulseTime));

        // Line Rendering with DoF Sharpness
        float lineTotal = exp(-dLine * coreSharpness) + exp(-dLine * haloSharpness) * 0.4;

        // Organic fade based on connection length
        float connFade = smoothstep(connRadius, connRadius * 0.5, dConn);

        layerColor += mix(baseCol, pulseCol, pulse * pulseInt) * lineTotal * connFade * fade * (0.3 + pulse * pulseInt);
    }
}

void main() {
    // 1. Correct Aspect Ratio UVs
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    // --- Portal Curvature ---
    float dist = length(uv);
    float angle = atan(uv.y, uv.x);

    // Twist the space as it gets closer to the center
    float twist = u_portal_twist / (dist + 0.1);
    float portalAngle = angle + twist;

    // Create new warped UVs for the neural network to live in
    vec2 portalUV = vec2(cos(portalAngle), sin(portalAngle)) * dist;

    // --- Interactive Mouse Parallax ---
    vec2 mouseOffset = (iMouse.z > 0.0) ? (iMouse.xy / iResolution.xy - 0.5) : vec2(0.0);

    // 2. Timing & Parameters
    float spd = (u_speed <= 0.0) ? 0.2 : u_speed;
    float t = iTime * spd;

    // Portal rhythmic pulsing
    float breathe = 1.0 + 0.15 * sin(t * 1.5); 

    float brightness = (u_intensity <= 0.0) ? 1.5 : u_intensity;
    float scaleBase = (u_scale <= 0.0) ? 1.0 : u_scale;
    float layerCount = clamp(u_layers, 1.0, 10.0);

    float density = (u_density <= 0.0) ? 1.0 : u_density * 2.0; 
    float connRadius = ((u_connection_radius <= 0.0) ? 1.5 : u_connection_radius * 2.5) * breathe;
    float pulseInt = (u_pulse_intensity <= 0.0) ? 1.5 : u_pulse_intensity * 3.0;

    // --- Dynamic Color Generation ---
    float hueBase = fract(0.55 + u_color_base + (t * u_color_cycle * 0.1));
    float huePulse = fract(0.10 + u_color_pulse + (t * u_color_cycle * 0.1));

    vec3 baseCol = hsv2rgb(vec3(hueBase, 0.85, 1.0));
    vec3 pulseCol = hsv2rgb(vec3(huePulse, 0.8, 1.0));

    // --- Event Horizon Background ---
    float eventHorizon = smoothstep(u_event_horizon + 0.1, u_event_horizon, dist);
    vec3 bgCenter = baseCol * 0.2; 
    vec3 bgEdge = vec3(0.005, 0.0, 0.02);
    vec3 finalColor = mix(bgEdge, bgCenter, exp(-dist * 2.0));

    // Deep black center
    finalColor *= (1.0 - eventHorizon);

    // 3. Layer Loop (Modified for Portal Depth)
    for(int i = 0; i < 10; i++) {
        float fi = float(i);
        if(fi >= layerCount) break;

        // Z moves inward towards the portal center
        float z = fract(fi * (1.0/layerCount) - t * 0.1); 
        float fade = smoothstep(0.0, 0.3, z) * smoothstep(1.0, 0.7, z);

        // Portal edge masking: elements fade as they enter the event horizon or get too far
        fade *= smoothstep(u_event_horizon, u_event_horizon + 0.2, dist);

        float blur = smoothstep(0.0, 0.5, abs(z - 0.5)); 
        float coreSharpness = mix(70.0, 15.0, blur);
        float haloSharpness = mix(20.0, 5.0, blur);

        // Size scales with "Z" depth and radial distance
        float size = mix(15.0, 2.0, z) * scaleBase * density;

        // Warp UVs for this layer
        vec2 layerUV = (portalUV + mouseOffset * (1.0 - z)) * size;
        layerUV *= rot(z * u_portal_twist + fi);

        vec2 id = floor(layerUV);
        vec2 f = fract(layerUV);

        vec3 layerColor = vec3(0.0);
        float layerNodes = 0.0;

        for(int y = -1; y <= 1; y++) {
            for(int x = -1; x <= 1; x++) {
                vec2 offs = vec2(float(x), float(y));
                vec2 p1 = offs + 0.5 + 0.4 * sin(t * 2.0 + hash22(id + offs) * 6.28);

                // Draw Node
                float dNode = length(f - p1);
                layerNodes += exp(-dNode * coreSharpness) + (exp(-dNode * haloSharpness) * 0.5);

                // Draw Connections
                addConnection(f, p1, offs, vec2(1.0, 0.0), id, t, coreSharpness, haloSharpness, fade, baseCol, pulseCol, connRadius, pulseInt, layerColor);
                addConnection(f, p1, offs, vec2(0.0, 1.0), id, t, coreSharpness, haloSharpness, fade, baseCol, pulseCol, connRadius, pulseInt, layerColor);
                addConnection(f, p1, offs, vec2(1.0, 1.0), id, t, coreSharpness, haloSharpness, fade, baseCol, pulseCol, connRadius, pulseInt, layerColor);
            }
        }

        // Add nodes
        layerColor += mix(baseCol, vec3(1.0), 0.7) * layerNodes * fade;

        // Add "Energy Sparks" pulled toward center
        vec2 dustPos = 0.5 + 0.4 * sin(t * 3.0 + hash22(id + 11.4) * 6.28);
        float dDust = length(f - dustPos);
        float dustGlow = exp(-dDust * coreSharpness * 1.5);
        layerColor += pulseCol * dustGlow * fade * pulseInt * 2.0;

        finalColor += layerColor * brightness * breathe * (1.0 - z * 0.5);
    }

    // --- Portal Rim Glow ---
    float rim = smoothstep(0.1, 0.0, abs(dist - (u_event_horizon + 0.05)));
    finalColor += baseCol * rim * 0.5 * breathe;

    // 4. Post-Processing
    float vig = 1.0 - length(uv0) * 0.8;
    finalColor *= smoothstep(0.0, 1.0, vig);

    // ACES-like Tone mapping
    finalColor = finalColor / (1.0 + finalColor * 0.15);
    finalColor = pow(finalColor, vec3(0.9));

    fragColor = vec4(finalColor, 1.0);
}
